import{_ as m,C as d,o as t,c as p,j as c,a as o,G as a,a3 as n,b as r,w as i,a9 as s}from"./chunks/framework.exbasbhr.js";const w=JSON.parse('{"title":"Toolbar Management System","description":"Toolbar Management System","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Toolbar Management System","description":"Toolbar Management System"},"headers":[],"relativePath":"en/dev/toolbar-system/index.md","filePath":"en/dev/toolbar-system/index.md"}'),g={name:"en/dev/toolbar-system/index.md"};function h(b,e,T,f,y,A){const u=d("ArticleMetadata"),l=d("Mermaid");return t(),p("div",null,[e[4]||(e[4]=c("h1",{id:"toolbar-management-system",tabindex:"-1"},[o("Toolbar Management System "),c("a",{class:"header-anchor",href:"#toolbar-management-system","aria-label":'Permalink to "Toolbar Management System"'},"​")],-1)),a(u),e[5]||(e[5]=n('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This document systematically introduces the toolbar management system of InkCanvasForClass, focusing on the following aspects:</p><ul><li>Architecture design and workflow of ToolbarHost: initialization, host bridging, view registration, and lookup.</li><li>ToolbarRegistry toolbar item registration, discovery, and management: rule evaluation, layout assembly, visibility control, configuration persistence, and dynamic loading.</li><li>Design philosophy and implementation specifications of the IToolbarItem interface: unified build workflow, default hiding strategies, localization, and icon resources.</li><li>Toolbar drag-and-drop sorting, custom configuration, and dynamic loading mechanisms: layout configuration files, condition rules, grouping, and separate borders.</li><li>Toolbar item state management, icon resources, and localization support: attached properties, styles, and resource binding.</li><li>Best practices and performance optimization recommendations: avoiding reflection overhead, reducing UI hierarchies, and using attached properties reasonably.</li></ul><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>The toolbar-related code is centralized under Ink Canvas/Controls/Toolbar, containing interfaces, hosts, registries, configuration models, built-in toolbar item base classes, and several concrete items; MainWindow completes the assembly and dynamic loading of the toolbar through ToolbarRegistry during initialization.</p>',5)),(t(),r(s,null,{default:i(()=>[a(l,{id:"mermaid-47",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22Toolbar%20Core%22%0AITH%5B%22IToolbarHost%20Interface%22%5D%0AITI%5B%22IToolbarItem%20Interface%22%5D%0ATH%5B%22ToolbarHost%20Implementation%22%5D%0ATR%5B%22ToolbarRegistry%20Registry%22%5D%0ATIC%5B%22ToolbarItemConfig%20Rules%20and%20Configuration%22%5D%0Aend%0Asubgraph%20%22Toolbar%20Item%20Implementation%22%0ATBB%5B%22ToolbarImageButtonItemBase%20Abstract%20Base%20Class%22%5D%0ACUR%5B%22CursorToolItem%22%5D%0APEN%5B%22PenToolItem%22%5D%0ACLR%5B%22ClearToolItem%22%5D%0ASEP%5B%22SeparatorToolItem%22%5D%0AERA%5B%22EraserToolItem%22%5D%0ASEL%5B%22SelectToolItem%22%5D%0Aend%0Asubgraph%20%22Host%20Integration%22%0AMW%5B%22MainWindow%20Initialization%22%5D%0AFB%5B%22Floating%20Bar%20Container%20StackPanelFloatingBarRoot%22%5D%0Aend%0AITH%20--%3E%20TH%0AITI%20--%3E%20TBB%0ATBB%20--%3E%20CUR%0ATBB%20--%3E%20PEN%0ATBB%20--%3E%20CLR%0ATBB%20--%3E%20ERA%0ATBB%20--%3E%20SEL%0AITI%20--%3E%20SEP%0ATH%20--%3E%20TR%0ATR%20--%3E%20TIC%0AMW%20--%3E%20TR%0ATR%20--%3E%20FB%0A"})]),fallback:i(()=>e[0]||(e[0]=[o(" Loading... ")])),_:1})),e[6]||(e[6]=n('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>IToolbarHost: The bridge interface between toolbar items and the host (MainWindow), providing window reference and view registration/lookup capabilities.</li><li>IToolbarItem: The minimum contract of a toolbar item, defining identifiers, display names, descriptions, default hiding rules, whether separate border is shown, whether hiding on drag-click is prevented, and responsible for building views.</li><li>ToolbarHost: The concrete implementation of IToolbarHost, holding the MainWindow reference and maintaining a mapping dictionary from id to view.</li><li>ToolbarRegistry: A static registry responsible for the automatic discovery of toolbar items, layout assembly, rule evaluation, visibility updates, reading/writing and backup/recovery of configuration files, and injecting the final UI into the host container.</li><li>ToolbarItemConfig: Rule and configuration models, including logical combinations of ToolbarRuleset/Group/Rule, condition sets, layout entries ToolbarComponentEntry, and their setting key-values.</li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>The operational workflow of the toolbar system is as follows:</p><ul><li>During MainWindow initialization, ToolbarHost is created, the current configuration file is loaded, and ToolbarRegistry.Populate is called to assemble the layout into the specified container.</li><li>ToolbarRegistry discovers all types implementing IToolbarItem via reflection, builds views, and registers them to ToolbarHost.</li><li>Each view applies styles such as size, alignment, margins, opacity, icon size, and colors according to the settings of ToolbarComponentEntry.</li><li>ToolbarRegistry flattens the entries into DisplayItems, segments them into &quot;separate border&quot; and &quot;content border&quot;, and generates a Border+StackPanel structure to inject into the container.</li><li>Visibility is determined jointly by ToolbarRuleset and context conditions (annotation mode, PPT mode, user collapsed state), and the visibility inside the container is recursively updated.</li></ul>',5)),(t(),r(s,null,{default:i(()=>[a(l,{id:"mermaid-111",class:"mermaid",graph:"sequenceDiagram%0Aparticipant%20MW%20as%20%22MainWindow%22%0Aparticipant%20TH%20as%20%22ToolbarHost%22%0Aparticipant%20TR%20as%20%22ToolbarRegistry%22%0Aparticipant%20CFG%20as%20%22Configuration%20File%22%0Aparticipant%20SP%20as%20%22StackPanelFloatingBarRoot%22%0AMW-%3E%3ETR%20%3A%20EnsureDefaultConfigExists()%0AMW-%3E%3ETH%20%3A%20new%20ToolbarHost(this)%0AMW-%3E%3ETR%20%3A%20LoadActiveConfig()%0ATR-%3E%3ECFG%20%3A%20Read%20%2F%20Backup%20Recovery%0AMW-%3E%3ETR%20%3A%20Populate(TH%2C%20SP%2C%20layout)%0ATR-%3E%3ETR%20%3A%20Discover()%20Reflection%20discovery%20of%20IToolbarItem%0Aloop%20Traverse%20layout%20entries%0ATR-%3E%3ETR%20%3A%20BuildAndRegister(item.BuildView(host))%0ATR-%3E%3ETH%20%3A%20RegisterView(id%2C%20view)%0ATR-%3E%3ETR%20%3A%20ApplyComponentSettings(view%2C%20entry)%0ATR-%3E%3ETR%20%3A%20SetHidingRuleset(view%2C%20ruleset)%0Aend%0ATR-%3E%3ESP%20%3A%20Inject%20bordered%20segments%0AMW-%3E%3ETR%20%3A%20UpdateVisibilityByMode(...)%0ATR-%3E%3ESP%20%3A%20Recursively%20evaluate%20rules%20and%20update%20visibility%0A"})]),fallback:i(()=>e[1]||(e[1]=[o(" Loading... ")])),_:1})),e[7]||(e[7]=n('<h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="toolbarhost-host-bridge-and-view-registration" tabindex="-1">ToolbarHost: Host Bridge and View Registration <a class="header-anchor" href="#toolbarhost-host-bridge-and-view-registration" aria-label="Permalink to &quot;ToolbarHost: Host Bridge and View Registration&quot;">​</a></h3><ul><li>Responsibilities <ul><li>Expose MainWindow reference, serving as the entry point for plugin-host interaction.</li><li>Maintain the mapping from id to FrameworkElement, supporting view lookups by id.</li></ul></li><li>Design Points <ul><li>Stores in a dictionary; registration/lookup are both O(1).</li><li>Defensive checks on null parameters to avoid exceptions.</li></ul></li><li>Collaboration with ToolbarRegistry <ul><li>After building each IToolbarItem view, ToolbarRegistry calls RegisterView to register it, enabling cross-component lookup via FindView later.</li></ul></li></ul>',3)),(t(),r(s,null,{default:i(()=>[a(l,{id:"mermaid-166",class:"mermaid",graph:"classDiagram%0Aclass%20IToolbarHost%20%7B%0A%2BWindow%20%3A%20MainWindow%0A%2BRegisterView(id%2C%20view)%20void%0A%2BFindView(id)%20FrameworkElement%0A%7D%0Aclass%20ToolbarHost%20%7B%0A-_views%20%3A%20Dictionary~string%2C%20FrameworkElement~%0A%2BWindow%20%3A%20MainWindow%0A%2BToolbarHost(window)%0A%2BRegisterView(id%2C%20view)%20void%0A%2BFindView(id)%20FrameworkElement%0A%7D%0AIToolbarHost%20%3C%7C..%20ToolbarHost%0A"})]),fallback:i(()=>e[2]||(e[2]=[o(" Loading... ")])),_:1})),e[8]||(e[8]=n('<h2 id="dependency-analysis" tabindex="-1">Dependency Analysis <a class="header-anchor" href="#dependency-analysis" aria-label="Permalink to &quot;Dependency Analysis&quot;">​</a></h2><ul><li>Component Coupling <ul><li>ToolbarRegistry depends on the implementations of IToolbarItem and the rules/configuration models of ToolbarItemConfig.</li><li>ToolbarHost only depends on the MainWindow reference and dictionary mapping, with low coupling.</li></ul></li><li>External Dependencies <ul><li>Configuration file read/write depends on Newtonsoft.Json and the file system.</li><li>Logging depends on LogHelper.</li></ul></li><li>Potential Circular Dependencies <ul><li>No circular dependencies found in the current structure; IToolbarItem implementations are injected into containers via ToolbarRegistry and do not have reverse dependencies on ToolbarRegistry.</li></ul></li></ul>',2)),(t(),r(s,null,{default:i(()=>[a(l,{id:"mermaid-218",class:"mermaid",graph:"graph%20LR%0ATR%5B%22ToolbarRegistry%22%5D%20--%3E%20ITI%5B%22IToolbarItem%20Implementation%22%5D%0ATR%20--%3E%20TIC%5B%22ToolbarItemConfig%22%5D%0ATR%20--%3E%20TH%5B%22ToolbarHost%22%5D%0ATH%20--%3E%20MW%5B%22MainWindow%22%5D%0AITI%20--%3E%20BTN%5B%22ToolbarImageButton%22%5D%0A"})]),fallback:i(()=>e[3]||(e[3]=[o(" Loading... ")])),_:1})),e[9]||(e[9]=n('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Reflection and Instantiation <ul><li>Discover scans and instantiates IToolbarItem through reflection; it is recommended to cache the results after the first use to avoid repeated scans.</li></ul></li><li>UI Hierarchy and Visibility <ul><li>Populate clears and rebuilds injected elements; when switching configurations frequently, consider partial updates instead of a full rebuild.</li><li>UpdateVisibilityByMode uses recursive traversal; it is recommended to limit the refresh frequency or perform batch updates when dealing with large toolbars.</li></ul></li><li>Resources and Styles <ul><li>ApplyComponentSettings sets multiple properties for each item; it is recommended to merge settings or defer their application.</li><li>Red styles and resource resolution might trigger resource lookups; it is recommended to handle them centrally or reuse resource references.</li></ul></li></ul><p>[This section is a general guideline and does not require a specific file source]</p><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Configuration File Issues <ul><li>When the main configuration is missing or corrupted, attempt to restore from backup; if it still fails, it will fall back to the default layout.</li><li>Check permissions and write protection on the configuration directory, and use a write protection manager if necessary.</li></ul></li><li>Toolbar Item Not Displayed <ul><li>Check if the IToolbarItem implementation is correctly discovered (non-abstract, non-interface, and instantiable).</li><li>Verify HidingRuleset against the current context (annotation/PPT/collapsed) to check the evaluation result.</li></ul></li><li>View Not Registered <ul><li>Confirm that BuildView returns a non-empty view and that it has been registered to ToolbarHost after BuildAndRegister.</li></ul></li><li>Events Not Responding <ul><li>Confirm that events are correctly bound in BuildView and that necessary host associations are completed in AfterBuild.</li></ul></li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Through a clear interface contract and registry pattern, this toolbar system achieves automatic discovery of toolbar items, flexible rule-driven visibility control, and extensible configuration persistence and dynamic loading. Utilizing the host bridge provided by ToolbarHost, plugins can easily access MainWindow capabilities; ToolbarImageButtonItemBase unifies the build workflow, localization, and icon resource handling of button-type items. It is recommended to follow interface specifications, use rule systems and component setting keys reasonably, and pay attention to performance and maintainability in practical extensions.</p><p>[This section is a summary and does not require a specific file source]</p><h2 id="appendix-custom-toolbar-item-development-guide" tabindex="-1">Appendix: Custom Toolbar Item Development Guide <a class="header-anchor" href="#appendix-custom-toolbar-item-development-guide" aria-label="Permalink to &quot;Appendix: Custom Toolbar Item Development Guide&quot;">​</a></h2><ul><li>Implementation Steps <ul><li>Create a new class implementing IToolbarItem or inheriting from ToolbarImageButtonItemBase.</li><li>Define a unique Id and DisplayName (localization keys can be used), and set DefaultHidingRuleset.</li><li>Create and configure the view in BuildView, bind events; if additional integration with host UI is needed, override AfterBuild.</li><li>Delegate the click logic to the corresponding handling method in MainWindow.</li></ul></li><li>Rules and Visibility <ul><li>Use ToolbarRuleset.AlwaysShow()/AnnotationOnly()/PptOnly()/PptAnnotationOnly() as starting points, overlaying WithHideOnCollapsed/WithPreventHideOnCollapsed if necessary.</li><li>Set hidingRuleset in the layout configuration or migrate to new rulesets.</li></ul></li><li>Component Settings <ul><li>Use ComponentSettingKeys to set sizes, alignments, margins, opacity, icon/font sizes, red style, etc.</li><li>For special controls (like a quick color palette), synchronize the display mode in AfterBuild.</li></ul></li><li>Localization and Icons <ul><li>Set label text and icon brushes via Strings.GetString or resource keys.</li><li>Icon geometry can be parsed from strings or set directly via resource keys.</li></ul></li><li>Best Practices <ul><li>Avoid performing time-consuming operations in BuildView, try to defer them to AfterBuild.</li><li>Keep the Id unique and stable to avoid conflicts with built-in items.</li><li>Reserve a place for the new item in the configuration file to facilitate user customization of sorting and grouping.</li></ul></li></ul>',10))])}const v=m(g,[["render",h]]);export{w as __pageData,v as default};
